<script setup lang="ts">
import {computed, onMounted, onUnmounted, ref, shallowReactive} from "vue";
import {useAuth} from "@papilio/auth";
import {item, query, request, type ConfigurationDraft, type CoreInstance, type NodeEndpoint, type NodeHealth, type NodeHealthCheck, type NodeQuality, type Page} from "@papilio/api";
import {faDate, faNumber} from "@papilio/ui";
const auth=useAuth();
function recordedPage<T>(path:()=>string){
  const state=shallowReactive({rows:[] as T[],page:1,pages:1,total:0,loading:false,error:""});
  let version=0,controller:AbortController|null=null;
  async function load():Promise<void>{
    const current=++version;controller?.abort();controller=new AbortController();const active=controller;state.loading=true;state.error="";
    try{const result=await request<Page<T>>(path(),"GET",undefined,{signal:active.signal});if(current!==version)return;state.rows=result.data;state.pages=result.meta.pager?.total_pages??1;state.total=result.meta.pager?.total_items??0;}
    catch(cause){if(current===version&&!active.signal.aborted)state.error=cause instanceof Error?cause.message:"Could not load recorded data.";}
    finally{if(current===version)state.loading=false;}
  }
  function reset():void{++version;controller?.abort();state.rows=[];state.page=1;state.pages=1;state.total=0;state.loading=false;state.error="";}
  onUnmounted(reset);return{state,load,reset};
}
const nodeQ=ref(""),coreQ=ref(""),node=ref<NodeEndpoint|null>(null),core=ref<CoreInstance|null>(null),configuration=ref<ConfigurationDraft|null>(null);
const nodes=recordedPage<NodeEndpoint>(():string=>`/v1/admin/network/nodes?${query({q:nodeQ.value,page:nodes.state.page})}`);
const cores=recordedPage<CoreInstance>(():string=>`/v1/admin/network/nodes/${node.value?.id}/cores?${query({q:coreQ.value,page:cores.state.page})}`);
const configurations=recordedPage<ConfigurationDraft>(():string=>`/v1/admin/network/configurations?${query({node_id:node.value?.id,core_id:core.value?.id,page:configurations.state.page})}`);
const health=recordedPage<NodeHealth>(():string=>`/v1/admin/network/health?${query({node_id:node.value?.id,page:health.state.page})}`);
const nodeHealth=computed(()=>health.state.rows.find(row=>row.node_id===node.value?.id)??null);
const source=ref(""),recordedSource=ref(""),quality=ref<NodeQuality[]>([]),qualityLoading=ref(false),qualityError=ref("");
let qualityVersion=0,qualityController:AbortController|null=null,alive=true;
const busy=ref(false),actionError=ref(""),notice=ref("");
async function chooseNode(row:NodeEndpoint):Promise<void>{if(busy.value)return;node.value=row;core.value=null;configuration.value=null;coreQ.value="";cores.reset();configurations.reset();health.reset();actionError.value="";notice.value="";await Promise.all([cores.load(),configurations.load(),health.load()]);}
async function chooseCore(row:CoreInstance|null):Promise<void>{if(busy.value)return;core.value=row;configuration.value=null;configurations.reset();await configurations.load();}
async function loadQuality():Promise<void>{
  if(source.value.trim().length<2)return;const network=source.value.trim(),version=++qualityVersion;qualityController?.abort();const controller=new AbortController();qualityController=controller;qualityLoading.value=true;qualityError.value="";
  try{const result=await request<{data:NodeQuality[]}>(`/v1/admin/network/quality?${query({client_network:network})}`,"GET",undefined,{signal:controller.signal});if(!alive||version!==qualityVersion)return;quality.value=result.data;recordedSource.value=network;}
  catch(cause){if(alive&&version===qualityVersion&&!controller.signal.aborted)qualityError.value=cause instanceof Error?cause.message:"Could not load recorded measurements.";}
  finally{if(alive&&version===qualityVersion)qualityLoading.value=false;}
}
async function recalculate():Promise<void>{
  const selected=node.value;if(!selected||busy.value||!auth.can("network","manage"))return;busy.value=true;actionError.value="";notice.value="";
  try{await item<NodeHealthCheck>(`/v1/admin/network/health/${selected.id}/check`,"POST");if(!alive)return;notice.value="Health recalculated from stored samples. No network probe was started.";await health.load();}
  catch(cause){if(alive)actionError.value=cause instanceof Error?cause.message:"Could not recalculate recorded health.";}
  finally{if(alive)busy.value=false;}
}
const healthLabels:Record<string,string>={disabled:"Disabled",unknown:"No measurements",stale:"Stale observations",insufficient:"Insufficient samples",healthy:"Healthy observations",degraded:"Degraded observations",unreachable:"Recorded checks failed"};
const configurationLink=computed(()=>configuration.value?{path:`/network/${configuration.value.node_id}/cores/${configuration.value.core_id}/configurations`,query:{configuration_id:configuration.value.id}}:null);
onMounted(nodes.load);onUnmounted(()=>{alive=false;++qualityVersion;qualityController?.abort();});
</script>
<template>
  <div class="page-head"><div><p class="eyebrow">CONNECTION LAB</p><h1>Inspect connection evidence</h1><p class="subtitle">Compare recorded reachability, inspect placement and open configuration tools.</p></div><RouterLink to="/network" class="btn secondary">Manage nodes</RouterLink></div>
  <div class="hint-box">Existing collectors record TCP reachability or TLS handshake latency. Legacy samples do not identify their measurement method. These observations do not prove authenticated proxy connectivity, throughput or the fastest route for a customer.</div>
  <section class="card card-pad lab-section"><h2>Choose a registered node</h2><form class="toolbar" @submit.prevent="nodes.state.page=1;nodes.load()"><label class="field"><span>Search node label or code</span><input v-model="nodeQ" maxlength="100" :disabled="busy"/></label><button class="btn secondary" :disabled="nodes.state.loading||busy">Search nodes</button></form><p v-if="nodes.state.error" class="message error" role="alert">{{nodes.state.error}}</p><p v-if="nodes.state.loading">Loading registered nodes…</p><div class="inline-actions"><button v-for="row in nodes.state.rows" :key="row.id" class="btn secondary" :aria-pressed="node?.id===row.id" :disabled="busy" @click="chooseNode(row)">{{row.label}} <span class="badge" :class="row.is_enabled?'success':'warning'">{{row.is_enabled?'Enabled':'Disabled'}}</span></button></div><p v-if="!nodes.state.loading&&!nodes.state.error&&!nodes.state.rows.length" class="empty">No registered nodes match this search.</p><div class="pager"><button :disabled="nodes.state.page<=1||nodes.state.loading||busy" @click="nodes.state.page--;nodes.load()">‹</button><span>{{faNumber(nodes.state.page)}} / {{faNumber(nodes.state.pages)}} · {{faNumber(nodes.state.total)}} nodes</span><button :disabled="nodes.state.page>=nodes.state.pages||nodes.state.loading||busy" @click="nodes.state.page++;nodes.load()">›</button></div></section>
  <section v-if="node" class="card card-pad lab-section"><div class="page-head"><div><h2>{{node.label}}</h2><p>{{node.protocol}} · {{node.is_enabled?'Delivery enabled':'Delivery disabled'}}</p></div><RouterLink :to="`/network/${node.id}/cores`" class="btn secondary">Core management</RouterLink><button class="btn secondary" :disabled="health.state.loading||busy" @click="health.load">Reload recorded health</button><button v-if="auth.can('network','manage')" class="btn" :disabled="busy" @click="recalculate">Recalculate recorded health</button></div>
    <p v-if="actionError||health.state.error" class="message error" role="alert">{{actionError||health.state.error}}</p><p v-if="notice" class="message success" role="status">{{notice}}</p><p v-if="health.state.loading">Loading health observations…</p><template v-else-if="nodeHealth"><span class="badge" :class="nodeHealth.status==='healthy'?'success':'warning'">{{healthLabels[nodeHealth.status]??nodeHealth.status}}</span><div class="detail-line"><span>Samples / successful</span><strong>{{faNumber(nodeHealth.sample_count)}} / {{faNumber(nodeHealth.successful_count)}}</strong></div><div class="detail-line"><span>Recorded average latency</span><strong>{{nodeHealth.average_latency_ms===null?'Unavailable':faNumber(nodeHealth.average_latency_ms)+' ms'}}</strong></div><div class="detail-line"><span>Last sample</span><strong>{{nodeHealth.last_sample_at?faDate(nodeHealth.last_sample_at):'No recorded sample'}}</strong></div><div class="detail-line"><span>Health calculated at</span><strong>{{faDate(nodeHealth.checked_at)}}</strong></div></template><p v-else-if="!health.state.error" class="empty">No health record exists for this node. Recalculation uses available stored samples and may report no measurements.</p>
    <h3>Core placement</h3><form class="toolbar" @submit.prevent="cores.state.page=1;cores.load()"><label class="field"><span>Search this node's cores</span><input v-model="coreQ" maxlength="100" :disabled="busy"/></label><button class="btn secondary" :disabled="cores.state.loading||busy">Search cores</button><button type="button" class="btn secondary" :disabled="busy" @click="chooseCore(null)">All cores</button></form><p v-if="cores.state.error" class="message error" role="alert">{{cores.state.error}}</p><p v-if="cores.state.loading">Loading cores…</p><div class="inline-actions"><button v-for="row in cores.state.rows" :key="row.id" class="btn secondary" :disabled="busy" :aria-pressed="core?.id===row.id" @click="chooseCore(row)">{{row.label}} · {{row.kind}}</button></div><p v-if="!cores.state.loading&&!cores.state.error&&!cores.state.rows.length">No cores are registered on this node.</p><div class="pager"><button :disabled="cores.state.page<=1||cores.state.loading||busy" @click="cores.state.page--;cores.load()">‹</button><span>{{faNumber(cores.state.page)}} / {{faNumber(cores.state.pages)}}</span><button :disabled="cores.state.page>=cores.state.pages||cores.state.loading||busy" @click="cores.state.page++;cores.load()">›</button></div>
    <h3>Configuration drafts {{core?'on '+core.label:''}}</h3><p v-if="configurations.state.error" class="message error" role="alert">{{configurations.state.error}}</p><p v-if="configurations.state.loading">Loading configuration drafts…</p><div class="inline-actions"><button v-for="row in configurations.state.rows" :key="row.id" class="btn secondary" :disabled="busy" :aria-pressed="configuration?.id===row.id" @click="configuration=row">{{row.label}} · {{row.protocol}} · {{faNumber(row.listen_port)}}</button></div><p v-if="!configurations.state.loading&&!configurations.state.error&&!configurations.state.rows.length">No configuration drafts exist in this placement.</p><div class="pager"><button :disabled="configurations.state.page<=1||configurations.state.loading||busy" @click="configurations.state.page--;configurations.load()">‹</button><span>{{faNumber(configurations.state.page)}} / {{faNumber(configurations.state.pages)}}</span><button :disabled="configurations.state.page>=configurations.state.pages||configurations.state.loading||busy" @click="configurations.state.page++;configurations.load()">›</button></div><RouterLink v-if="configurationLink" :to="configurationLink" class="btn">Open selected configuration tools</RouterLink><p v-if="configuration">The record workspace includes settings JSON, client profiles and available exports. Full server JSON and private downloads require network management permission. A saved draft is not an applied or tested core.</p>
  </section>
  <section class="card card-pad lab-section"><h2>Recorded source-network comparison</h2><form class="toolbar" @submit.prevent="loadQuality"><label class="field"><span>Measurement source network</span><input v-model="source" minlength="2" maxlength="64" required placeholder="e.g. mobile access network"/></label><button class="btn secondary" :disabled="qualityLoading||source.trim().length<2">Compare recorded observations</button></form><p>Ranking follows the configured sample window and minimum success policy. Use observations from the customer's own access network; a node's location does not establish their route quality.</p><p v-if="qualityError" class="message error" role="alert">{{qualityError}}</p><p v-if="qualityLoading">Loading recorded observations…</p><p v-if="recordedSource">Showing recorded source: <strong>{{recordedSource}}</strong></p><div class="table-wrap"><table class="data-table"><thead><tr><th>Node</th><th>Protocol</th><th>Samples / successful</th><th>Average latency</th><th>Recorded score</th></tr></thead><tbody><tr v-for="row in quality" :key="row.node_id"><td>{{row.label}}</td><td>{{row.protocol}}</td><td>{{faNumber(row.sample_count)}} / {{faNumber(row.successful_count)}}</td><td>{{row.average_latency_ms===null?'Unavailable':faNumber(row.average_latency_ms)+' ms'}}</td><td>{{row.score===null?'Insufficient eligible data':faNumber(row.score)}}</td></tr></tbody></table></div><p v-if="recordedSource&&!qualityLoading&&!qualityError&&!quality.length" class="empty">No eligible observations are recorded for this source network.</p></section>
  <section class="card card-pad lab-section"><h2>Advanced tools</h2><div class="form-grid"><div><h3>Core JSON workspace</h3><p>Open an actual configuration above to review managed or experimental Xray/sing-box JSON where the core supports it. Settings and exports remain tied to that selected record.</p></div><div><h3>Authenticated benchmarks <span class="badge warning">Not yet available</span></h3><p>Durable tests for authenticated tunnel connectivity, jitter, loss and bounded transfer speed require a trusted test runner and explicit measurement contracts.</p></div><div><h3>Structured load balancing <span class="badge warning">Not yet available</span></h3><p>Automatic failover, weighted selection and latency policies need capability-aware exports and verified observations. Delivery groups currently bundle connection options; they do not prove traffic balancing.</p><RouterLink to="/host-groups" class="btn secondary">Manage delivery groups</RouterLink></div></div></section>
</template>
<style scoped>.lab-section{margin-top:20px}h3{margin-top:20px}</style>
